<?php
session_start();
if (!isset($_SESSION["user_id"])) { die("Please log in first."); }
require "db.php";
$user_id = (int)$_SESSION["user_id"];
$query = mysqli_prepare($conn, "SELECT t.*,a.status AS assignment_status FROM task_assignments a JOIN tasks t ON a.task_id=t.task_id WHERE a.user_id=? ORDER BY a.assigned_at DESC");
mysqli_stmt_bind_param($query, "i", $user_id); mysqli_stmt_execute($query); $tasks = mysqli_stmt_get_result($query);
?>
