</div></div></div><script>var filterButton=document.getElementById('filter-tasks');var sortButton=document.getElementById('sort-tasks');var assignments=document.getElementsByClassName('assigned-row');var activeOnly=false;var earliestFirst=true;filterButton.addEventListener('click',function(){activeOnly=!activeOnly;for(var i=0;i<assignments.length;i++){if(activeOnly){assignments[i].style.display=assignments[i].getAttribute('data-status')==='delivered'?'none':'';}else{assignments[i].style.display='';}}filterButton.textContent=activeOnly?'Show All':'Filter';});sortButton.addEventListener('click',function(){var rows=[];for(var i=0;i<assignments.length;i++){rows.push(assignments[i]);}rows.sort(function(first,second){var firstTime=first.getAttribute('data-pickup-time');var secondTime=second.getAttribute('data-pickup-time');if(firstTime<secondTime){return earliestFirst?-1:1;}if(firstTime>secondTime){return earliestFirst?1:-1;}return 0;});for(var i=0;i<rows.length;i++){rows[i].parentNode.appendChild(rows[i]);}sortButton.textContent=earliestFirst?'Sort by Time ↓':'Sort by Time ↑';earliestFirst=!earliestFirst;});</script></body></html>
